import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BTLSZHNB.js";const b=JSON.parse('{"title":"SQLiteDatabase — takoform_sqlite_database","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/sqlite-database.md","filePath":"proposals/edge/sqlite-database.md"}'),r={name:"proposals/edge/sqlite-database.md"};function s(n,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="sqlitedatabase-—-takoform-sqlite-database" tabindex="-1">SQLiteDatabase — <code>takoform_sqlite_database</code> <a class="header-anchor" href="#sqlitedatabase-—-takoform-sqlite-database" aria-label="Permalink to &quot;SQLiteDatabase — `takoform_sqlite_database`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A worker keeps relational application state — accounts, jobs, inventories — in one embedded SQLite database. Workers consume it through <code>module-worker.sqlite</code> bindings.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The database has no desired fields; SQLite semantics are the identity, not a configuration.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>Exactly the <code>edge.sql@1.0.0</code> contract: execute/query/transaction with bound parameters, SQLite&#39;s SQL dialect and dynamic typing, serializable transactions applying atomically over a single consistent snapshot, <code>busy</code> under write contention, and closed errors.</p><p>Values are TAGGED by storage class — null, integer, real, text, blob — so a 64-bit INTEGER (canonical decimal text) and a BLOB (base64) round-trip losslessly instead of being flattened into a JSON scalar that cannot hold them. Every statement reports the same result whether it ran alone or inside a transaction, so a <code>SELECT</code> inside a transaction returns its rows (decision 0020).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>SQL dialect, typing, and isolation are what application code is written against. An <code>engine</code> token selecting SQLite versus other engines would make one desired document mean different systems on different hosts — exactly what decision 0008 prohibits.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A Postgres or MySQL database is a different Form in a managed-database family. Migration bytes and applying their ordered history are separate <code>SQLiteMigrationSet</code> and <code>SQLiteMigrationApplication</code> resources; the database identity does not absorb schema rollout policy.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>edge.sql@1.0.0</code>.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; it is a binding target (<code>module-worker.sqlite</code>).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a database bound by any Worker Version must fail with <code>dependency_in_use</code>. Delete destroys the data; portable state never carries backups or connection material.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The embedded per-application SQLite database of a proven edge platform. The retained v1alpha2 <code>RelationalDatabase</code> candidate, whose open <code>engine</code> token this Form replaces by fixing SQLite as the shape.</p>',20)])])}const m=a(r,[["render",s]]);export{b as __pageData,m as default};
